pub const Nfa = union(enum) {
    /// consume a single expected byte and advance to next1
    char: struct { next1: State, byte: u8 },
    /// '.' - consume any byte and advance to next1
    any: struct { next1: State },
    /// fork execution to next1 and next2 without consuming input
    split: struct { next1: State, next2: State },
    /// '^' - match only at start of input or newline in multiline mode
    bol: struct { next1: State, absolute_anchor: bool },
    /// '$' - match only at end of input or newline in multiline mode
    eol: struct { next1: State, mode: Token.Boundary },
    /// '[a-z]' - match a character class (< 128)
    class: Class,
    /// '\W', '\D', '\S' - like .class but matches when not in the mask.
    ///
    /// A negated class like \D must also match codepoints ≥ 128, which CharMask
    /// can't represent. adding a negated bool field to .class would bloat Nfa.
    /// .negated_class distinguishes without the bloat.
    negated_class: Class,
    /// full byte class used for multi-byte chains. emitted for
    /// codepoint classes and for '.'.
    class_bytes: struct { next1: State, mask: CharMask256 },
    /// non-ascii literal codepoint (≥ 128)
    codepoint: struct { next1: State, value: u21 },
    /// unicode character class
    class_codepoint: struct { next1: State, bitmap: Bitmap },
    /// save capture position
    save: struct { next1: State, slot: u8 },
    /// '\C' - consume any single byte unconditionally
    any_byte: struct { next1: State },
    /// '\b' - match only at word boundary
    /// '\B' - match only at non-word boundary
    word_boundary: struct { next1: State, negated: bool },
    /// terminal match state
    match,

    }

pub const Diagnostic = struct {
    offset: u16 = 0,
    length: u16 = 0,
    message: ?[]const u8 = null,
}

pub const Compilation = struct {
    /// an NFA state graph.
    states: []Nfa,
    /// entry point index into `states`.
    start: State,
    /// number of capture groups present in `states` as pairs of `.save` entries.
    /// equal to number of `.save` entries / 2.
    num_capture_groups: u8,
    flags: Regex.Flags,

    }

pub const Flags = packed struct(u5) {
    /// 'i'.  When false, character classes match both lower and uppercase letters.
    case_insensitive: bool = false,
    /// 'm'.
    multiline: bool = false,
    /// 's'.  When true, '.' (dot) matches '\n' (newline) in addition to any other
    /// character.
    dot_matches_newline: bool = false,
    /// 'u'.  When utf8, the input is decoded from UTF8 bytes into Unicode
    /// codepoints and matching happens at the codepoint level. Multi-byte
    /// sequences are consumed as single codepoints.  Captures and match
    /// lengths are returned in byte offsets.
    encoding: enum(u1) { latin1, utf8 } = .latin1,
    /// When true, disables Perl extensions.  i.e. reject `{n,m}??`, lazy
    /// quantifiers, non-capturing groups.
    posix_syntax: bool = false,
    // TODO 'U' swap_greedy
    // TODO scoped_flags

    }

pub const Options = struct {
    diagnostic: ?*Diagnostic = null,
    max_program_states: u16 = 1024 * 16,
    flags: Flags = .{},
}

pub const Capture = struct {
    positions: []usize,
    matched: bool,
    len: u32,
    group_count: u8,

    }

pub const Token = union(enum) {
    /// literal byte
    char: u8,
    /// non-ascii literal codepoint
    codepoint: u21,
    /// '.'
    dot,
    /// () or empty alternative
    empty,
    class: CharMask,
    negated_class: CharMask,
    class_utf8: Bitmap,
    /// ^ .line, \A .absolute
    caret: Boundary,
    /// $ .line, \z .absolute
    dollar: Boundary,
    star: Greediness,
    plus: Greediness,
    repeat: struct { min: u32, max: u32, greediness: Greediness },
    question: Greediness,
    lparen,
    /// (:?
    lparen_nocapture,
    rparen,
    pipe,
    any_byte,
    word_boundary,
    not_word_boundary,
    flags_change: struct { flags: Regex.Flags, change: Regex.Flags.Set },
    /// implicit, inserted during lex
    concat,

    }

pub const empty: Capture = .{
        .matched = false,
        .len = 0,
        .positions = &.{},
        .group_count = 0,
    }

pub const Tag = E: {
            const ninfo = @typeInfo(Node).@"union";
            const I = @Int(.unsigned, @bitSizeOf(ninfo.tag_type.?));
            break :E @Enum(I, .exhaustive, std.meta.fieldNames(Node), &std.simd.iota(I, ninfo.fields.len));
        }
